#include <iostream>
#include <string>
#include <stack>
bool isValid(const std::string& s){
  std::stack<char> st;
  for(char c: s){
    if(c=='('||c=='['||c=='{') st.push(c);
    else { if(st.empty()) return false; char t=st.top(); st.pop();
      if((c==')'&&t!='(')||(c==']'&&t!='[')||(c=='}'&&t!='{')) return false; }
  }
  return st.empty();
}
int main(){ std::cout << (isValid("()[]{}") ? 1 : 0); }
